$ErrorActionPreference = 'Stop'
Set-Location D:\repository\skills\cursor-model-routing
$tasks = Get-Content .\tasks.json -Raw -Encoding UTF8 | ConvertFrom-Json
$t3 = ($tasks.tasks | Where-Object { $_.id -eq 'T3' }).prompt

function Call($model) {
  $body = @{ model = $model; messages = @(@{ role = 'user'; content = $t3 }); max_tokens = 1024; temperature = 0.2 } | ConvertTo-Json -Depth 8
  $sw = [System.Diagnostics.Stopwatch]::StartNew()
  try {
    $resp = Invoke-RestMethod -Uri "http://127.0.0.1:3425/v1/chat/completions" -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 240
    $sw.Stop()
    [pscustomobject]@{ model = $model; ok = $true; ms = $sw.ElapsedMilliseconds; content = $resp.choices[0].message.content }
  } catch {
    $sw.Stop()
    [pscustomobject]@{ model = $model; ok = $false; ms = $sw.ElapsedMilliseconds; content = "ERR: $($_.Exception.Message)" }
  }
}

$out = @()
foreach ($rep in 1..3) {
  foreach ($m in @('cursor/composer-2.5', 'cursor/grok-4.7@256k')) {
    $r = Call $m
    $r | Add-Member -NotePropertyName rep -NotePropertyValue $rep
    # 是否跑题：出现无关关键词 skill-upgrade / SkillUpgradeTracker / instruction.md 视为 off-task
    $offTask = ($r.content -match 'SkillUpgradeTracker|skill-upgrade|instruction\.md|TDD')
    $r | Add-Member -NotePropertyName off_task -NotePropertyValue $offTask
    Write-Output ("rep{0} {1,-24} ok={2} {3}ms offTask={4}" -f $rep, $m, $r.ok, $r.ms, $offTask)
    Write-Output ("   head: " + ($r.content.Substring(0, [math]::Min(160, $r.content.Length)) -replace "`n", " "))
    $out += $r
  }
}
$out | ConvertTo-Json -Depth 6 | Set-Content .\results\t3-repro.json -Encoding UTF8
Write-Output "wrote results/t3-repro.json"

