$ErrorActionPreference = 'Stop'
Set-Location D:\repository\skills\cursor-model-routing
$tasks = Get-Content .\tasks.json -Raw -Encoding UTF8 | ConvertFrom-Json
function Head($s,$n=120){ if($s.Length -gt $n){$s.Substring(0,$n)}else{$s} }
function OffTask($s){
  # 序列/模板泄漏特征：第X轮、【ID】/Title/Difficulty、助手/用户对话、SkillUpgradeTracker、面试题
  return ($s -match '第\s*\d+\s*轮|【ID】|【Title】|【Difficulty】|SkillUpgradeTracker|skill-upgrade|面试题|##\s*助手|###\s*助手')
}
function Call($model,$prompt){
  $body = @{ model = $model; messages = @(@{ role = 'user'; content = $prompt }); max_tokens = 1024; temperature = 0.2 } | ConvertTo-Json -Depth 8
  $sw = [System.Diagnostics.Stopwatch]::StartNew()
  try {
    $resp = Invoke-RestMethod -Uri "http://127.0.0.1:3425/v1/chat/completions" -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 240
    $sw.Stop(); return [pscustomobject]@{ ok=$true; ms=$sw.ElapsedMilliseconds; content=$resp.choices[0].message.content }
  } catch { $sw.Stop(); return [pscustomobject]@{ ok=$false; ms=$sw.ElapsedMilliseconds; content="ERR: $($_.Exception.Message)" } }
}
$out = @()
foreach ($tid in @('T5','T7','T2','T1')) {
  $prompt = ($tasks.tasks | Where-Object { $_.id -eq $tid }).prompt
  foreach ($rep in 1..3) {
    $r = Call 'cursor/composer-2.5' $prompt
    $off = OffTask $r.content
    Write-Output ("composer {0} rep{1} ok={2} {3}ms offTask={4} clen={5}" -f $tid,$rep,$r.ok,$r.ms,$off,$r.content.Length)
    Write-Output ("   head: " + ((Head $r.content) -replace "`n"," "))
    $out += [pscustomobject]@{ model='cursor/composer-2.5'; task=$tid; rep=$rep; ok=$r.ok; ms=$r.ms; off_task=$off; clen=$r.content.Length; content=$r.content }
  }
}
$out | ConvertTo-Json -Depth 6 | Set-Content .\results\composer-repro.json -Encoding UTF8
Write-Output "wrote results/composer-repro.json"
